{
  "findings": [
    {
      "check_id": "CKV_AWS_1",
      "title": "Ensure IAM policies do not allow full administrative privileges or wildcard resources for sensitive actions",
      "resource": "aws_iam_policy.privesc-sageMakerCreatePresignedNotebookURL-policy",
      "severity": "HIGH",
      "explanation": "The policy grants 'sagemaker:CreatePresignedNotebookInstanceUrl' on Resource '*'. This allows any principal with this policy to generate presigned URLs for ANY SageMaker notebook instance in the account, potentially bypassing network controls and accessing data from notebooks they do not own. It should be scoped to specific ARNs."
    }
  ],
  "patched_code": "resource "aws_iam_policy" "privesc-sageMakerCreatePresignedNotebookURL-policy" {
  name        = "privesc-sageMakerCreatePresignedNotebookURL-policy"
  path        = "/"
  description = "Allows privesc via sagemakerCreatePresignedNotebookURL"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action = [
          "sagemaker:CreatePresignedNotebookInstanceUrl",
          "sagemaker:ListNotebookInstances"
        ]
        # TODO: Replace '*' with specific Notebook Instance ARNs to prevent cross-account/resource access
        Resource = "*"
      },
    ]
  })
}",
  "fix_summary": "Added a TODO comment highlighting that the Resource attribute must be scoped to specific ARNs instead of using a wildcard '*' to prevent unauthorized access to all SageMaker notebook instances. The code structure remains valid Terraform, but the security risk is explicitly flagged for remediation as hardcoding specific ARNs requires external context not present in the file."
}
